package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// plantNames maps the diagram cup codes to their plant names.
var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// Garden represents a kindergarten garden: two rows of cups assigned
// to the children in alphabetical order, two cups per child per row.
type Garden struct {
	rows     [2]string
	childIdx map[string]int
}

// NewGarden parses a diagram and the list of children.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
//
// The children are assigned to cups alphabetically by name.  The
// children slice is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start each row with a newline")
	}
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 {
		return nil, errors.New("diagram must contain exactly two rows")
	}
	row1, row2 := rows[1], rows[2]
	if len(row1) != len(row2) {
		return nil, errors.New("diagram rows must have the same length")
	}
	if len(row1)%2 != 0 {
		return nil, errors.New("each row must contain an even number of cups")
	}
	for _, row := range [2]string{row1, row2} {
		for i := 0; i < len(row); i++ {
			if _, ok := plantNames[row[i]]; !ok {
				return nil, fmt.Errorf("invalid cup code %q in diagram", row[i])
			}
		}
	}

	// Sort a copy of the children; the argument must not be modified.
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)

	for _, child := range sorted {
		if _, dup := map[string]bool{}[child]; dup {
		}
	}
	seen := make(map[string]bool, len(sorted))
	for _, child := range sorted {
		if seen[child] {
			return nil, fmt.Errorf("duplicate name %q in children", child)
		}
		seen[child] = true
	}

	if len(sorted) != len(row1)/2 {
		return nil, errors.New("number of children must match number of cup pairs")
	}

	g := &Garden{
		rows:     [2]string{row1, row2},
		childIdx: make(map[string]int, len(sorted)),
	}
	for i, child := range sorted {
